window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-263cca5b7ab5af86"]={"versions": [{"id": "FIG-263cca5b7ab5af86", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (UML Activity Diagram) zur Spezifikation eines algorithmischen Kontrollflusses.\n</li><li><strong>Architektonische Einordnung:</strong> AUTOSAR E2E Library (<code>AUTOSAR_FO_PRS_E2EProtocol</code>, R23-11).\n</li><li><strong>Technischer Zweck:</strong> Normative Spezifikation des Einzelschritts „Write Counter“ innerhalb der Schutzfunktion <code>E2E_P11Protect()</code> für das E2E-Profil 11 gem. [[PRS_E2E_00512]](file:///docs/pipeline/PRS_E2E_00512). Der Schritt sichert Safety-relevante Botschaften (bis ASIL D) gegen Übertragungsfehler wie Botschaftsverlust, Wiederholung, Einfügen und Vertauschen der Reihenfolge über einen 4-Bit Alive-Counter ab.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitäts-Scope:</strong>\n<ul class=\"fig-list\"><li><code>E2E_P11Protect()</code>: Synchrone Bibliotheksfunktion der E2E-Library zur Absicherung von Sendedaten.\n</li></ul>\n</li><li><strong>Datenstrukturen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li><code>Config</code> (<code>E2E_P11ConfigType*</code>): Konfigurationsstruktur mit dem Member <code>CounterOffset</code> (Bit-Offset des Counters im Nutzdatenarray).\n</li><li><code>State</code> (<code>E2E_P11ProtectStateType*</code>): Zustandsstruktur des Senders mit dem Member <code>Counter</code> (Wertebereich 0x0 bis 0xE; 4-Bit Alive-Counter).\n</li><li><code>Data</code> / <code>DataPtr</code> (<code>uint8*</code>): Linearer Byte-Puffer der zu schützenden PDU.\n</li></ul>\n</li><li><strong>Adressierungs- &amp; Bit-Arithmetik (Note-Element):</strong>\n<ul class=\"fig-list\"><li>Byte-Index: <code>Config-&gt;CounterOffset &gt;&gt; 3</code> (entspricht <code>CounterOffset / 8</code>).\n</li><li>Bit-Position / Shift im Zielbyte: <code>Config-&gt;CounterOffset &amp; 0x7</code> (entspricht <code>CounterOffset % 8</code>).\n</li><li>Daten-Maskierung: <code>(State-&gt;Counter &amp; 0x0F) &lt;&lt; (Config-&gt;CounterOffset &amp; 0x7)</code>.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initial Node:</strong> Eintritt in die Sub-Aktivität nach optionalem Schreiben des Data-ID-Nibbles (<code>Write DataIDNibble</code>, Abb. 6.96).\n</li><li><strong>Action Node („Write Counter“):</strong>\n<ol class=\"fig-list\"><li>Auslesen und Maskieren der niederwertigen 4 Bits aus <code>State-&gt;Counter</code> (<code>State-&gt;Counter &amp; 0x0F</code>).\n</li><li>Berechnung des Zielbytes im Array via Rechtsshift um 3 Bits.\n</li><li>Berechnung des Bit-Shifts innerhalb des Zielbytes via Bitmaske <code>0x07</code>.\n</li><li>Bitweises Schreiben des 4-Bit-Wertes an die berechnete Position im Puffer <code>Data[]</code> unter Beibehaltung der Little-Endian-Konvention.\n</li></ol>\n</li><li><strong>Activity Final Node:</strong> Verlassen des Teilschritts; deterministischer Übergang zur anschließenden CRC-Berechnung (<code>Compute CRC</code>).\n</li><li><strong>Laufzeit-Charakteristik:</strong> Rein synchron, nicht blockierend, keine Callbacks, keine Fehlermeldungen (Det/Dem) in diesem Teilschritt, deterministische Zeitkomplexität O(1).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Verbindlichkeit:</strong> [[PRS_E2E_00512]](file:///docs/pipeline/PRS_E2E_00512) bindet das Verhalten von <code>E2E_P11Protect()</code> direkt an dieses Diagramm zur Erfüllung von [[RS_E2E_08539]](file:///docs/pipeline/RS_E2E_08539).\n</li><li><strong>Read-Modify-Write-Pflicht:</strong> Das Diagramm spezifiziert nur das Einfügen der Bits (<code>&lt;&lt;</code>). In der realen C-Implementierung im Treiber/Stack muss das Zielbyte via Read-Modify-Write maskiert werden (<code>Data[byte] = (Data[byte] &amp; ~(0x0F &lt;&lt; shift)) | ((State-&gt;Counter &amp; 0x0F) &lt;&lt; shift)</code>), um das benachbarte Nibble nicht mit Nullen zu überschreiben.\n</li><li><strong>Nibble-Alignment:</strong> <code>Config-&gt;CounterOffset</code> muss auf eine 4-Bit-Grenze (Nibble-Alignment, Bit 0 oder 4) parametriert werden, da E2E P11 keinen byteübergreifenden Split des 4-Bit-Counters unterstützt.\n</li><li><strong>Bit-Ordnung:</strong> Gemäß AUTOSAR-Konvention für Little-Endian entspricht Bit 0 dem Least Significant Bit (LSB) innerhalb des jeweiligen Bytes.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-447f41bf11a5410b", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (UML Activity Diagram) zur Spezifikation eines algorithmischen Kontrollflusses.\n</li><li><strong>Architektonische Einordnung:</strong> AUTOSAR E2E Library (<code>AUTOSAR_FO_PRS_E2EProtocol</code>, R23-11).\n</li><li><strong>Technischer Zweck:</strong> Normative Spezifikation des Einzelschritts „Write Counter“ innerhalb der Schutzfunktion <code>E2E_P11Protect()</code> für das E2E-Profil 11 gem. [[PRS_E2E_00512]](file:///docs/pipeline/PRS_E2E_00512). Der Schritt sichert Safety-relevante Botschaften (bis ASIL D) gegen Übertragungsfehler wie Botschaftsverlust, Wiederholung, Einfügen und Vertauschen der Reihenfolge über einen 4-Bit Alive-Counter ab.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitäts-Scope:</strong>\n<ul class=\"fig-list\"><li><code>E2E_P11Protect()</code>: Synchrone Bibliotheksfunktion der E2E-Library zur Absicherung von Sendedaten.\n</li></ul>\n</li><li><strong>Datenstrukturen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li><code>Config</code> (<code>E2E_P11ConfigType*</code>): Konfigurationsstruktur mit dem Member <code>CounterOffset</code> (Bit-Offset des Counters im Nutzdatenarray).\n</li><li><code>State</code> (<code>E2E_P11ProtectStateType*</code>): Zustandsstruktur des Senders mit dem Member <code>Counter</code> (Wertebereich 0x0 bis 0xE; 4-Bit Alive-Counter).\n</li><li><code>Data</code> / <code>DataPtr</code> (<code>uint8*</code>): Linearer Byte-Puffer der zu schützenden PDU.\n</li></ul>\n</li><li><strong>Adressierungs- &amp; Bit-Arithmetik (Note-Element):</strong>\n<ul class=\"fig-list\"><li>Byte-Index: <code>Config-&gt;CounterOffset &gt;&gt; 3</code> (entspricht <code>CounterOffset / 8</code>).\n</li><li>Bit-Position / Shift im Zielbyte: <code>Config-&gt;CounterOffset &amp; 0x7</code> (entspricht <code>CounterOffset % 8</code>).\n</li><li>Daten-Maskierung: <code>(State-&gt;Counter &amp; 0x0F) &lt;&lt; (Config-&gt;CounterOffset &amp; 0x7)</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initial Node:</strong> Eintritt in die Sub-Aktivität nach optionalem Schreiben des Data-ID-Nibbles (<code>Write DataIDNibble</code>, Abb. 6.96).\n</li><li><strong>Action Node („Write Counter“):</strong>\n<ol class=\"fig-list\"><li>Auslesen und Maskieren der niederwertigen 4 Bits aus <code>State-&gt;Counter</code> (<code>State-&gt;Counter &amp; 0x0F</code>).\n</li><li>Berechnung des Zielbytes im Array via Rechtsshift um 3 Bits.\n</li><li>Berechnung des Bit-Shifts innerhalb des Zielbytes via Bitmaske <code>0x07</code>.\n</li><li>Bitweises Schreiben des 4-Bit-Wertes an die berechnete Position im Puffer <code>Data[]</code> unter Beibehaltung der Little-Endian-Konvention.\n</li></ol>\n</li><li><strong>Activity Final Node:</strong> Verlassen des Teilschritts; deterministischer Übergang zur anschließenden CRC-Berechnung (<code>Compute CRC</code>).\n</li><li><strong>Laufzeit-Charakteristik:</strong> Rein synchron, nicht blockierend, keine Callbacks, keine Fehlermeldungen (Det/Dem) in diesem Teilschritt, deterministische Zeitkomplexität O(1).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Verbindlichkeit:</strong> [[PRS_E2E_00512]](file:///docs/pipeline/PRS_E2E_00512) bindet das Verhalten von <code>E2E_P11Protect()</code> direkt an dieses Diagramm zur Erfüllung von [[RS_E2E_08539]](file:///docs/pipeline/RS_E2E_08539).\n</li><li><strong>Read-Modify-Write-Pflicht:</strong> Das Diagramm spezifiziert nur das Einfügen der Bits (<code>&lt;&lt;</code>). In der realen C-Implementierung im Treiber/Stack muss das Zielbyte via Read-Modify-Write maskiert werden (<code>Data[byte] = (Data[byte] &amp; ~(0x0F &lt;&lt; shift)) | ((State-&gt;Counter &amp; 0x0F) &lt;&lt; shift)</code>), um das benachbarte Nibble nicht mit Nullen zu überschreiben.\n</li><li><strong>Nibble-Alignment:</strong> <code>Config-&gt;CounterOffset</code> muss auf eine 4-Bit-Grenze (Nibble-Alignment, Bit 0 oder 4) parametriert werden, da E2E P11 keinen byteübergreifenden Split des 4-Bit-Counters unterstützt.\n</li><li><strong>Bit-Ordnung:</strong> Gemäß AUTOSAR-Konvention für Little-Endian entspricht Bit 0 dem Least Significant Bit (LSB) innerhalb des jeweiligen Bytes.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5079c742fe869fbc", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (UML Activity Diagram) zur Spezifikation eines algorithmischen Kontrollflusses.\n</li><li><strong>Architektonische Einordnung:</strong> AUTOSAR E2E Library (<code>AUTOSAR_FO_PRS_E2EProtocol</code>, R23-11).\n</li><li><strong>Technischer Zweck:</strong> Normative Spezifikation des Einzelschritts „Write Counter“ innerhalb der Schutzfunktion <code>E2E_P11Protect()</code> für das E2E-Profil 11 gem. [[PRS_E2E_00512]](file:///docs/pipeline/PRS_E2E_00512). Der Schritt sichert Safety-relevante Botschaften (bis ASIL D) gegen Übertragungsfehler wie Botschaftsverlust, Wiederholung, Einfügen und Vertauschen der Reihenfolge über einen 4-Bit Alive-Counter ab.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitäts-Scope:</strong>\n<ul class=\"fig-list\"><li><code>E2E_P11Protect()</code>: Synchrone Bibliotheksfunktion der E2E-Library zur Absicherung von Sendedaten.\n</li></ul>\n</li><li><strong>Datenstrukturen &amp; Parameter:</strong>\n<ul class=\"fig-list\"><li><code>Config</code> (<code>E2E_P11ConfigType*</code>): Konfigurationsstruktur mit dem Member <code>CounterOffset</code> (Bit-Offset des Counters im Nutzdatenarray).\n</li><li><code>State</code> (<code>E2E_P11ProtectStateType*</code>): Zustandsstruktur des Senders mit dem Member <code>Counter</code> (Wertebereich 0x0 bis 0xE; 4-Bit Alive-Counter).\n</li><li><code>Data</code> / <code>DataPtr</code> (<code>uint8*</code>): Linearer Byte-Puffer der zu schützenden PDU.\n</li></ul>\n</li><li><strong>Adressierungs- &amp; Bit-Arithmetik (Note-Element):</strong>\n<ul class=\"fig-list\"><li>Byte-Index: <code>Config-&gt;CounterOffset &gt;&gt; 3</code> (entspricht <code>CounterOffset / 8</code>).\n</li><li>Bit-Position / Shift im Zielbyte: <code>Config-&gt;CounterOffset &amp; 0x7</code> (entspricht <code>CounterOffset % 8</code>).\n</li><li>Daten-Maskierung: <code>(State-&gt;Counter &amp; 0x0F) &lt;&lt; (Config-&gt;CounterOffset &amp; 0x7)</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initial Node:</strong> Eintritt in die Sub-Aktivität nach optionalem Schreiben des Data-ID-Nibbles (<code>Write DataIDNibble</code>, Abb. 6.96).\n</li><li><strong>Action Node („Write Counter“):</strong>\n<ol class=\"fig-list\"><li>Auslesen und Maskieren der niederwertigen 4 Bits aus <code>State-&gt;Counter</code> (<code>State-&gt;Counter &amp; 0x0F</code>).\n</li><li>Berechnung des Zielbytes im Array via Rechtsshift um 3 Bits.\n</li><li>Berechnung des Bit-Shifts innerhalb des Zielbytes via Bitmaske <code>0x07</code>.\n</li><li>Bitweises Schreiben des 4-Bit-Wertes an die berechnete Position im Puffer <code>Data[]</code> unter Beibehaltung der Little-Endian-Konvention.\n</li></ol>\n</li><li><strong>Activity Final Node:</strong> Verlassen des Teilschritts; deterministischer Übergang zur anschließenden CRC-Berechnung (<code>Compute CRC</code>).\n</li><li><strong>Laufzeit-Charakteristik:</strong> Rein synchron, nicht blockierend, keine Callbacks, keine Fehlermeldungen (Det/Dem) in diesem Teilschritt, deterministische Zeitkomplexität O(1).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Verbindlichkeit:</strong> [[PRS_E2E_00512]](file:///docs/pipeline/PRS_E2E_00512) bindet das Verhalten von <code>E2E_P11Protect()</code> direkt an dieses Diagramm zur Erfüllung von [[RS_E2E_08539]](file:///docs/pipeline/RS_E2E_08539).\n</li><li><strong>Read-Modify-Write-Pflicht:</strong> Das Diagramm spezifiziert nur das Einfügen der Bits (<code>&lt;&lt;</code>). In der realen C-Implementierung im Treiber/Stack muss das Zielbyte via Read-Modify-Write maskiert werden (<code>Data[byte] = (Data[byte] &amp; ~(0x0F &lt;&lt; shift)) | ((State-&gt;Counter &amp; 0x0F) &lt;&lt; shift)</code>), um das benachbarte Nibble nicht mit Nullen zu überschreiben.\n</li><li><strong>Nibble-Alignment:</strong> <code>Config-&gt;CounterOffset</code> muss auf eine 4-Bit-Grenze (Nibble-Alignment, Bit 0 oder 4) parametriert werden, da E2E P11 keinen byteübergreifenden Split des 4-Bit-Counters unterstützt.\n</li><li><strong>Bit-Ordnung:</strong> Gemäß AUTOSAR-Konvention für Little-Endian entspricht Bit 0 dem Least Significant Bit (LSB) innerhalb des jeweiligen Bytes.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-263cca5b7ab5af86", "to": "FIG-447f41bf11a5410b", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Oberer Bildbeschnitt: Die im Vorgängerbild am oberen Rand sichtbaren Textfragmente der vorangehenden Spezifikationszeile („behave as shown in Figure 6.97...] (RS_E2E_...“) wurden vollständig abgeschnitten.\n</li></ul>"}, {"from": "FIG-447f41bf11a5410b", "to": "FIG-5079c742fe869fbc", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
